create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text,role text not null default 'student' check(role in ('student','teacher','admin')),avatar_url text,created_at timestamptz default now());
create table if not exists public.courses(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,description text default '',category text default 'general',duration_months int default 3,lessons_per_month int default 20,published boolean default true,created_at timestamptz default now());
create table if not exists public.teachers(id uuid primary key default gen_random_uuid(),profile_id uuid references public.profiles(id) on delete set null,full_name text not null,specialty text default '',experience_years int default 0,bio text default '',avatar_url text,active boolean default true,created_at timestamptz default now());
create table if not exists public.enrollments(id uuid primary key default gen_random_uuid(),student_id uuid references public.profiles(id) on delete cascade,course_id uuid references public.courses(id) on delete cascade,status text default 'active',progress numeric(5,2) default 0,enrolled_at timestamptz default now(),unique(student_id,course_id));
create table if not exists public.lessons(id uuid primary key default gen_random_uuid(),course_id uuid references public.courses(id) on delete cascade,title text not null,description text default '',lesson_order int default 1,video_url text,content text default '',published boolean default true,created_at timestamptz default now());
create table if not exists public.applications(id uuid primary key default gen_random_uuid(),full_name text not null,phone text not null,age int,course text,mode text default 'Offline',note text default '',status text default 'New',created_at timestamptz default now());
create table if not exists public.schedule(id uuid primary key default gen_random_uuid(),weekday int,start_time time,end_time time,course_id uuid references public.courses(id),teacher_id uuid references public.teachers(id),room text default '',active boolean default true);
create table if not exists public.tests(id uuid primary key default gen_random_uuid(),course_id uuid references public.courses(id) on delete cascade,title text not null,description text default '',published boolean default true);
create table if not exists public.test_questions(id uuid primary key default gen_random_uuid(),test_id uuid references public.tests(id) on delete cascade,question text not null,points numeric default 1,question_order int default 1);
create table if not exists public.homework(id uuid primary key default gen_random_uuid(),course_id uuid references public.courses(id) on delete cascade,title text not null,description text default '',due_at timestamptz,attachment_url text,published boolean default true);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
alter table public.profiles enable row level security;alter table public.courses enable row level security;alter table public.teachers enable row level security;alter table public.enrollments enable row level security;alter table public.lessons enable row level security;alter table public.applications enable row level security;alter table public.schedule enable row level security;alter table public.tests enable row level security;alter table public.test_questions enable row level security;alter table public.homework enable row level security;
create policy "public courses" on public.courses for select using(published or public.is_admin());create policy "public teachers" on public.teachers for select using(active or public.is_admin());create policy "public lessons" on public.lessons for select using(published or public.is_admin());create policy "public schedule" on public.schedule for select using(active or public.is_admin());create policy "submit applications" on public.applications for insert with check(true);create policy "admin applications" on public.applications for all using(public.is_admin()) with check(public.is_admin());create policy "own profile" on public.profiles for select using(id=auth.uid() or public.is_admin());create policy "admin profiles" on public.profiles for all using(public.is_admin()) with check(public.is_admin());create policy "admin courses" on public.courses for all using(public.is_admin()) with check(public.is_admin());create policy "admin teachers" on public.teachers for all using(public.is_admin()) with check(public.is_admin());create policy "own enrollments" on public.enrollments for select using(student_id=auth.uid() or public.is_admin());create policy "admin enrollments" on public.enrollments for all using(public.is_admin()) with check(public.is_admin());create policy "admin schedule" on public.schedule for all using(public.is_admin()) with check(public.is_admin());create policy "admin lessons" on public.lessons for all using(public.is_admin()) with check(public.is_admin());create policy "admin tests" on public.tests for all using(public.is_admin()) with check(public.is_admin());create policy "admin questions" on public.test_questions for all using(public.is_admin()) with check(public.is_admin());create policy "admin homework" on public.homework for all using(public.is_admin()) with check(public.is_admin());grant usage on schema public to anon,authenticated;grant select on public.courses,public.teachers,public.lessons,public.schedule to anon,authenticated;grant insert on public.applications to anon,authenticated;grant select,insert,update,delete on all tables in public to authenticated;
